package cc.huevia.ncp;

/** Unmodified NX Studio NP2 exports; provenance is beside the binary fixtures. */
public final class Np2Fixtures {
    private Np2Fixtures() { }
    public static byte[] std() { return hex(""); }
    public static byte[] flat() { return hex(""); }
    public static byte[] mono() { return hex(""); }
    private static byte[] hex(String text) {
        byte[] b = new byte[text.length() / 2];
        for (int i = 0; i < b.length; i++) b[i] = (byte) Integer.parseInt(text.substring(i*2, i*2+2), 16);
        return b;
    }
}
